const path = "_commentary/v16/out/s089/discovery/session-20261005/sec1/terra/list.tsv";
const cmds = [
  ["rows", `wc -l ${path}`],
  ["fields", `awk -F '\\t' 'NF != 4 {print NR \":\" NF}' ${path}`],
  ["labels", `awk -F '\\t' '$1 !~ /^(strong|medium|weak|contrast)$/ {print NR \":\" $1}' ${path}`],
  ["refs", `awk -F '\\t' '$2 !~ /^[0-9]+:[0-9]+$/ || $2 ~ /^89:/ {print NR \":\" $2}' ${path}`],
  ["dupes", `awk -F '\\t' '{n[$2]++; line[$2]=line[$2] \" \" NR} END {for (r in n) if (n[r] > 1) print r \":\" n[r] \":\" line[r]}' ${path}`],
  ["bases", `awk -F '\\t' '$3 !~ /^(scene|root|theme|speaker|contrast|neighbour)(\\+(scene|root|theme|speaker|contrast|neighbour))*$/ {print NR \":\" $3}' ${path}`]
];
const out = await Promise.allSettled(cmds.map(([name, cmd]) =>
  tools.exec_command({cmd, workdir:"/Volumes/aro/projects/prose_generation", yield_time_ms:10000, max_output_tokens:3000})
));
out.forEach((v,i)=> {
  text(cmds[i][0] + ":");
  text(v.status === "fulfilled" ? (v.value.output || "(clean)") : String(v.reason));
});
